-- Carga de archivos oficiales. Generado por importar_oficial.py; idempotente.
-- Archivos: ventas.202609.txt, bloqueo.2609.txt, mant.preventivo.09.10.txt
USE paqrap;
SET NAMES utf8mb4;
START TRANSACTION;

-- Archivos fuente (los que ya existen con ese nombre se conservan).
ON DUPLICATE KEY UPDATE nombre = nombre;
SET @arch0 = (SELECT id FROM archivo_fuente WHERE nombre = 'ventas.202609.txt');
SET @arch1 = (SELECT id FROM archivo_fuente WHERE nombre = 'bloqueo.2609.txt');
SET @arch2 = (SELECT id FROM archivo_fuente WHERE nombre = 'mant.preventivo.09.10.txt');

-- Ubicaciones (2731) y clientes (3885) que falten.

-- ventas.202609.txt: 5000 pedidos.
DROP TEMPORARY TABLE IF EXISTS stg_pedido;
CREATE TEMPORARY TABLE stg_pedido (n INT UNSIGNED PRIMARY KEY, cliente VARCHAR(32), x TINYINT UNSIGNED, y TINYINT UNSIGNED, cantidad INT UNSIGNED, registrado DATETIME, plazo INT UNSIGNED, original VARCHAR(255));
SELECT @arch0, s.n, CONCAT('P-', LPAD(s.n, 5, '0')), s.cliente, u.id, s.cantidad, s.registrado, s.plazo, DATE_ADD(s.registrado, INTERVAL s.plazo HOUR), s.original
FROM stg_pedido s JOIN ubicacion u ON u.x = s.x AND u.y = s.y
ON DUPLICATE KEY UPDATE pedido.id = pedido.id;
DROP TEMPORARY TABLE stg_pedido;

-- bloqueo.2609.txt: 558 bloqueos, 1703 vertices.
DROP TEMPORARY TABLE IF EXISTS stg_vertice;
CREATE TEMPORARY TABLE stg_vertice (linea INT UNSIGNED, orden SMALLINT UNSIGNED, x TINYINT UNSIGNED, y TINYINT UNSIGNED, PRIMARY KEY (linea, orden));
SELECT b.id, v.orden, u.id FROM stg_vertice v
JOIN bloqueo b ON b.archivo_id = @arch1 AND b.numero_linea = v.linea
JOIN ubicacion u ON u.x = v.x AND u.y = v.y
ON DUPLICATE KEY UPDATE bloqueo_vertice.ubicacion_id = bloqueo_vertice.ubicacion_id;
DROP TEMPORARY TABLE stg_vertice;

-- mant.preventivo.09.10.txt: 37 jornadas de mantenimiento.

COMMIT;

-- Comprobacion: pedidos, bloqueos y mantenimientos por archivo fuente.
SELECT a.tipo, a.nombre,
  CASE a.tipo WHEN 'VENTAS' THEN (SELECT COUNT(*) FROM pedido p WHERE p.archivo_id = a.id)
              WHEN 'BLOQUEOS' THEN (SELECT COUNT(*) FROM bloqueo b WHERE b.archivo_id = a.id)
              ELSE (SELECT COUNT(*) FROM mantenimiento_programado m WHERE m.archivo_id = a.id) END AS filas
FROM archivo_fuente a WHERE a.nombre IN ('ventas.202609.txt', 'bloqueo.2609.txt', 'mant.preventivo.09.10.txt')
ORDER BY a.id;
